<script setup>
import {computed,reactive} from 'vue';
import {backgroundModes,normalizeBackground} from '../sceneBackground.js';
import NumberRange from './NumberRange.vue';
import PaletteColor from './PaletteColor.vue';
const props=defineProps({studio:Object}),s=reactive(props.studio);
const b=computed(()=>normalizeBackground(s.current.background));
function set(field,value){s.current.background={...b.value,[field]:value};}
const colors=computed(()=>new Proxy(b.value,{set(_,field,value){set(field,value);return true;}}));
const presets=[['Sombre à points','#101820','#ffffff','dots'],['Papier à points','#faf9f6','#182126','dots'],['Grille technique','#101820','#7dcbb8','grid'],['Lignes obliques','#f5f4f0','#405568','lines']];
function preset(p){s.current.background=normalizeBackground({mode:p[3],base:p[1],color:p[2],opacity:18,rotation:p[3]==='lines'?35:0});}
</script>
<template><div class="background-properties"><p class="field-help">Fond de cette composition, conservé dans les exports. Les calques opaques placés devant peuvent le masquer.</p><div class="background-presets"><button v-for="p in presets" :key="p[0]" :title="p[0]" :aria-label="p[0]" @click="preset(p)"><span :style="{backgroundColor:p[1],color:p[2]}">⠿</span>{{p[0]}}</button></div><label>Type de fond<select aria-label="Type de fond" :value="b.mode" @change="set('mode',$event.target.value)"><option v-for="[id,label] in backgroundModes" :key="id" :value="id">{{label}}</option></select></label><template v-if="!['inherit','transparent'].includes(b.mode)"><PaletteColor :element="colors" field="base" label="Couleur du fond" :theme="s.theme"/><PaletteColor v-if="b.mode==='gradient'" :element="colors" field="color2" label="Deuxième couleur" :theme="s.theme"/><template v-if="!['solid','gradient'].includes(b.mode)"><PaletteColor :element="colors" field="color" label="Couleur du motif" :theme="s.theme"/><NumberRange label="Opacité du motif" unit="%" :model-value="b.opacity" @update:model-value="set('opacity',$event)"/><NumberRange v-if="!['grid','lines'].includes(b.mode)" label="Taille du motif" unit="px" :min="1" :max="100" :model-value="b.size" @update:model-value="set('size',$event)"/><NumberRange label="Espacement du motif" unit="px" :min="8" :max="240" :model-value="b.spacing" @update:model-value="set('spacing',$event)"/><NumberRange v-if="['grid','lines','crosses','hexagons'].includes(b.mode)" label="Épaisseur du motif" unit="px" :min="0.5" :max="12" :step="0.5" :model-value="b.thickness" @update:model-value="set('thickness',$event)"/><label v-if="!['grid','lines'].includes(b.mode)" class="checkbox-label"><input type="checkbox" :checked="b.stagger" @change="set('stagger',$event.target.checked)">Disposition en quinconce</label><NumberRange v-for="[field,label] in [['offsetX','Décalage horizontal'],['offsetY','Décalage vertical']]" :key="field" :label="label" unit="px" :min="-240" :max="240" :model-value="b[field]" @update:model-value="set(field,$event)"/></template><NumberRange v-if="b.mode!=='solid'" label="Rotation du fond" unit="°" :min="-180" :max="180" :model-value="b.rotation" @update:model-value="set('rotation',$event)"/></template></div></template>
<style scoped>
.background-properties{display:grid;gap:14px}.background-properties :deep(label){margin-top:0}.background-properties>.field-help{margin:0}.background-presets{display:grid;grid-template-columns:1fr 1fr;gap:6px}.background-presets button{display:flex;align-items:center;gap:7px;text-align:left;border:1px solid var(--border);border-radius:7px;padding:7px;background:transparent;color:inherit;font:inherit;font-size:11px;cursor:pointer}.background-presets button:hover{border-color:var(--mint)}.background-presets span{display:grid;place-items:center;border-radius:4px;width:28px;height:28px;flex-shrink:0;font-size:24px}
</style>
